Here is a javascript class that describes a BasicGame:

```
class BasicGame {
    constructor (roomId,io) {
        this.players = {};
        this.io = io;
        this.roomId = roomId;
        this.isPlaying = false;
        this.maxPlayers = 1;
    }

    Start (data = null) {
      this.isPlaying = true;
    }

    Restart (data = null) {
        this.isPlaying = true;
    }

    Finish (data = null) {
        this.isPlaying = false;
    }

    PlayMove(data = null) {}

    AddPlayer(socketId){
        if (Object.keys(this.players).length >= this.maxPlayers) return false;

        this.players[socketId] = {id : socketId};
        if (Object.keys(this.players).length == this.maxPlayers) this.Start();
    }
}
```

