        _.each(meta.fields, (field, key) => {
          acc.fields[key].value = field.value;
        });
      }

      if (!acc?.mode || acc?.mode !== 'created' || ['deleted', 'signed'].includes(meta?.mode)) {
        acc.mode = meta.mode;
        acc.userName = item.name;
      }

      if (meta.mergedTo) {
        acc.mergedTo = meta.mergedTo;
      }

      acc.processedItems.push(item._id);

      return acc;
    },
    {
      fields: {},
      mode: '',
      mergedTo: '',
      userName: '',
      processedItems: [],
    },
  );
}

