нужно чтобы запрос был  передан в parsing() и обработан внутри функции `parsing()` и помещен в `QStringList`
#include "function.h"
#include "singleton.h"

void parsing(QSqlQuery q)
{
    QString command = q.value(0).toString();

    if (command == "reg") {
        QString login = q.value(1).toString();
        QString password = q.value(2).toString();
        if (registerUser(login, password)) {
            qDebug() << "User successfully registered!";
        } else {
            qDebug() << "Error registering user!";
        }
    } else if (command == "auth") {
        QString login = q.value(1).toString();
        QString password = q.value(2).toString();
        if (authUser(login, password)) {
            qDebug() << "User successfully authorized!";
        } else {
            qDebug() << "Error authorizing user!";
        }
    } else if (command == "get_users") {
        if (authUser(q.value(1).toString(), q.value(2).toString())) {
            getUsers(q);
        } else {
            qDebug() << "You are not authorized!";
        }
    }
}

bool registerUser(QString login, QString password)
{
    Singleton& db = Singleton::getInstance();
    QSqlQuery q;
    q.prepare("INSERT INTO users (login, password) VALUES (:login, :password)");
    q.bindValue(":login", login);
    q.bindValue(":password", password);
    if (!q.exec()) {
        qDebug() << "Error registering user!";
        qDebug() << q.lastError().text();
    }
    return q.exec();
}

bool authUser(QString login, QString password)
{
    Singleton& db = Singleton::getInstance();
    QSqlQuery q;
    q.prepare("SELECT * FROM users WHERE login = :login AND password = :password");
    q.bindValue(":login", login);
    q.bindValue(":password", password);
    if (q.exec() && q.first()) {
        return true;
    }
    return false;
}

void getUsers(QSqlQuery q)
{
    Singleton& db = Singleton::getInstance();
    QSqlQuery query;
    if (!query.exec("SELECT * FROM users")) {
        qDebug() << "Error selecting users!";
        qDebug() << q.lastError().text();
    }
    query.exec("SELECT * FROM users");
    while (query.next()) {
        q.exec("INSERT INTO response (login) VALUES ('" + query.value(0).toString() + "')");
    }
}

