# -*- coding: utf8 -*-
"""
Hexalife : hexagonal grid for a game of life
"""
#Standard imports
import random
import time
import tkinter
#http://tkinter.fdex.eu/index.html (doc tkinter)

#Static
SQR3 = 1.732050807568877
RADIUS = 4
XDIST, YDIST = 3 * RADIUS, 1.5 * SQR3 * RADIUS
OFFSET = 1.5 * RADIUS
ltDELTAS = [(0, RADIUS * SQR3), (RADIUS * 1.5, RADIUS * SQR3 / 2), (RADIUS * 1.5, - RADIUS * SQR3 / 2), (0, - RADIUS * SQR3), (- RADIUS * 1.5, - RADIUS * SQR3 / 2), (- RADIUS * 1.5, RADIUS * SQR3 / 2)]
XLEN, YLEN = 240 // RADIUS, 240 // RADIUS

#-CLASS-------------------------------------------------------------------------
class Chrono():
	"""Estimate time spent running"""
	def __enter__(self):
		self.start = time.time_ns()

	def __exit__(self, exception_type, exception_value, exception_traceback):
		self.duration = time.time_ns() - self.start
		print('%s: %s ns' % (self.message, longint2str(self.duration)))

	def __init__(self, message):
		self.message = message
		self.start = None

#-FUNCTION----------------------------------------------------------------------
def longint2str(value):
	"""Return an user friendly string of given long value"""
	s = str(value)
	return('.'.join([s[0:len(s)%3]] + [s[i:i+3] for i in range((len(s) % 3), len(s), 3)]))

#-CLASS-------------------------------------------------------------------------
class Main():
	"""Main"""
	def __init__(self):
		self.count = 0
		self.dTiles = {}
		self.myWindow = tkinter.Tk()
		self.myCanvas = tkinter.Canvas(self.myWindow, width = 800, height = 720, bd = 0, bg = '#888888', highlightthickness = 0)
		self.myCanvas.pack()
		self.run = True
		for x in range(XLEN):
			for y in range(YLEN): self.dTiles[(x, y)] = Tile(self, x, y)
		for (x, y) in self.dTiles:
			for (nx, ny) in [(x - 1 + y % 2, y - 1), (x + y % 2, y - 1), (x - 1, y), (x + 1, y), (x - 1 + y % 2, y + 1), (x + y % 2, y + 1)]:
				mx, my = nx % XLEN, ny % YLEN #Connected borders
				#mx, my = nx, ny #Separate borders
				if (mx, my) in self.dTiles: self.dTiles[(x, y)].isnear(self.dTiles[(mx, my)])
		self.delay = len(self.dTiles) // 10
		self.myWindow.after(0, self.turn)
		self.myWindow.bind('<Any-KeyPress>', self.event_keypress)
		self.myWindow.mainloop()

	def event_keypress(self, anEvent = None):
		"""Handles keyboard usage"""
		if anEvent.keysym == 'Escape': exit()
		elif anEvent.keysym == 'space': self.run = not self.run
		elif anEvent.keysym == 'r':
			self.count = 0
			for aTile in self.dTiles.values(): aTile.alivechance()
		elif anEvent.keysym == 'c':
			self.count = 0
			for aTile in self.dTiles.v

def event_leave(self, anEvent = None):
		"""Mouse leaves tile surface"""
		if self.focus:
			self.focus = False
			self.myCanvas.itemconfigure(self.tag, outline = '')

	def isnear(self, aTile):
		"""Return True if near to given tile"""
		return(aTile in self.lTiles)

	def linkedto(self, aTile):
		"""Given tile added to neighbours"""
		self.lTiles.append(aTile)

	def nearcount(self):
		"""Count of occupied near tiles"""
		return([aTile.alive or aTile.next for aTile in self.lTiles].count(True))

	def refresh(self):
		"""Refresh tile display"""
		self.myCanvas.itemconfigure(self.tag, fill = self.colour)

	def update(self):
		"""Update alive status and display"""
		#old colours were Red : death, Green : birth, Blue : alive, Grey : empty
		if not self.start and not self.end: self.colour = {(True, True): '#0000ff', (True, False): '#999999', (False, True): '#6666ff', (False, False): '#999999'}[(self.alive, self.next)]
		self.alive = self.next
		self.refresh()

#-CLASS-------------------------------------------------------------------------
class Tracker():
	"""Draw attention to a specific part of the screen"""
	def __init__(self, aCanvas):
		self.myCanvas = aCanvas
		self.tag = self.myCanvas.create_oval((0, 0), (32, 32), outline = '')

	def goto(self, x, y):
		"""Goes to given position"""
		self.myCanvas.itemconfigure(self.tag, outline = '#ffffff')
		self.myCanvas.coords(self.tag, x - 16, y - 16, x + 16, y + 16)

	def hide(self):
		"""Disappears"""
		self.myCanvas.itemconfigure(self.tag, outline = '')

#-MAIN--------------------------------------------------------------------------
if __name__ == '__main__': Main()

