        clink.Candle = rc
        clink.Technical = make(map[string]*Technical)

        if cc.Last == nil {
                clink.Previous = nil
                clink.Next = nil
                cc.Last = &clink
                cc.First = &clink
                cc.ActualDepth = cc.ActualDepth + 1
                return
        }

        clink.Previous = cc.Last
        clink.Next = nil

        if clink.Previous.Candle.NextTime == clink.Candle.StartTime {
                clink.Previous.Candle.NextTime = clink.Candle.StartTime
        } else {
                logger.Debug("breaking chain At " + TimeOfCandle(clink.Previous.Candle.NextTime) + " is different from " + TimeOfCandle(clink.Candle.StartTime) )
        }
        cc.Last = &clink
