const { registerBlockType } = wp.blocks;
const { RichText } = wp.editor;
const { useEffect, useState } = wp.element;

registerBlockType( 'mi-plugin/listado-cabeceras', {
    title: 'Listado de Cabeceras',
    icon: 'editor-ul',
    category: 'formatting',
    edit: ( props ) => {
        const [ headings, setHeadings ] = useState( [] );

        useEffect( () => {
            const post = wp.data.select( 'core/editor' ).getCurrentPost();
            const newHeadings = post.content.match( /<h([1-6]).*?>(.*?)<\/h[1-6]>/g ).map( ( heading ) => {
                const matches = heading.match( /<h([1-6]).*?>(.*?)<\/h[1-6]>/ );
                return {
                    level: matches[1],
                    text: matches[2],
                };
            } );
            const nestedHeadings = newHeadings.reduce( ( acc, heading ) => {
                let currentLevel = acc;
                for ( let i = heading.level - 1; i < currentLevel.length; i++ ) {
                    if ( ! currentLevel[ i ].children ) {
                        currentLevel[ i ].children = [];
                    }
                    currentLevel = currentLevel[ i ].children;
                }
                currentLevel.push( {
                    text: heading.text,
                    children: [],
                } );
                return acc;
            }, [] );
            setHeadings( nestedHeadings );
        }, [ props.clientId ] );

        const renderHeadings = ( headings ) => {
            return (
                <ul>
                    { headings.map( ( heading, index ) => (
                        <li key={ index }>
                            <RichText.Content value={ heading.text } />
                            { heading.children && heading.children.length > 0 ? renderHeadings( heading.children ) : [] }
                        </li>
                    ) ) }
                </ul>
            );
        };

        return (
            <div className={ props.className }>
                { renderHeadings( headings ) }
            </div>
        );
    },
    save: () => {
        return null;
