    def updateLabelText(self):
        font = self.label.font()
        available_width = self.width() - self.label.contentsMargins().left() - self.label.contentsMargins().right()
        self.short_message = (self.original_text[0:124].replace("\n", "¶")[:121].rstrip() + "...") \
            if len(self.original_text) > 125 else self.original_text.replace("\n", "¶")  # shorten
        if not self.parent() or self.size() == QSize(0, 0) or not self.isVisible() or not self.layout():
            return ""  # Not ready, return default
        truncated_text = self.short_message[:self.calculateTruncationPoint(font, available_width)]
        if not self.short_message == truncated_text:
            truncated_text += ".."
        self.label.setText(truncated_text)

    def calculateTruncationPoint(self, font, available_width):
        elide_marker = ".."
        font_metrics = QFontMetrics(font)
        if len(self.short_message) < 20:
            return len(self.short_message)
        text_width = font_metrics.horizontalAdvance(self.short_message)
        marker_width = font_metrics.horizontalAdvance(elide_marker)
        for i in range(18, 120, 2):
            truncated_text = self.short_message[:i] + elide_marker
            truncated_width = font_metrics.horizontalAdvance(truncated_text)
            if truncated_width + marker_width >= available_width or i > 110:
                return i - 2
        return 0

