<script>
var txtData = [];
var currentIndex = 0;

// This function loads the TXT file into memory.
function loadTXT() {
  // Get the TXT file from the file input.
  var txtFile = document.getElementById("txtFile").files[0];

  // If the file is not empty, create a new FileReader and read the data from the file.
  if (txtFile) {
    var reader = new FileReader();

    // When the data is loaded, update the list of items.
    reader.onload = function() {
      var data = reader.result;
      txtData = data.split("\n");
      updateList();
    };

    // Read the data from the file.
    reader.readAsText(txtFile);
  } else {
    // Show an error message if the file is empty.
    alert("Please select a file.");
  }
}

// This function updates the list of items in the document.
function updateList() {
  // Get the list of items.
  var list = document.getElementById("txtList");

  // Clear the list.
  list.innerHTML = "";

  // For each item in the TXT data, create a new <li> element and add it to the list.
  for (var i = 0; i < txtData.length; i++) {
    var li = document.createElement("li");
    li.innerHTML = txtData[i];
    list.appendChild(li);
  }
}

