    var startTime: String = ""
    var destroyedAsteroids: Int = 0
    var score: Int = 0
    var asteroids: List<Asteroid> = emptyList()

    fun destroyAsteroid(ast: Asteroid) {
        destroyedAsteroids++
        score += ast.mass * ast.radius
    }
}

